adcs_vec3_t rel_vec, axis_unit;
double n_pred, n_meas, dot_abs, innovation;
unint32 reject_next;

/* 合法性检查：非法输入/配置直接锁 FAULT */
if ((st_input.predicted == NULL) || (st_input.measured == NULL) ||
    (st_input.enable != 0 && st_input.enable != 1) ||
    (!isfinite(st_config.accept_rad)) || (!isfinite(st_config.reject_rad)) ||
    (st_config.accept_rad < 0.0) || (st_config.accept_rad >= st_config.reject_rad) ||
    (st_config.reject_rad > ADCS_PI) ||
    (st_config.max_rejects < 1U) || (st_config.max_rejects > 20U)) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    st_output.rejects = st_state.rejects;
    st_output.innovation_rad = 0.0;
    st_output.axis = (adcs_vec3_t){0, 0, 0};
    return;
}

n_pred = st_input.predicted->w * st_input.predicted->w + st_input.predicted->x * st_input.predicted->x +
         st_input.predicted->y * st_input.predicted->y + st_input.predicted->z * st_input.predicted->z;
n_meas = st_input.measured->w * st_input.measured->w + st_input.measured->x * st_input.measured->x +
         st_input.measured->y * st_input.measured->y + st_input.measured->z * st_input.measured->z;
if ((!isfinite(n_pred)) || (!isfinite(n_meas)) ||
    (n_pred <= ADCS_EPS_QUAT) || (n_meas <= ADCS_EPS_QUAT)) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    st_output.rejects = st_state.rejects;
    st_output.innovation_rad = 0.0;
    st_output.axis = (adcs_vec3_t){0, 0, 0};
    return;
}

/* 归一化 predicted/measured */
(void)adcs_quat_normalize(st_input.predicted, &pred_n);
(void)adcs_quat_normalize(st_input.measured, &meas_n);

/* 相对四元数 rel = measured * conjugate(predicted) */
pred_conj = adcs_quat_conjugate(&pred_n);
rel = adcs_quat_multiply(&meas_n, &pred_conj);

/* 符号不变最短角: innovation = 2*acos(|w|) */
dot_abs = fabs(rel.w);
if (dot_abs > 1.0) dot_abs = 1.0;
innovation = 2.0 * acos(dot_abs);

/* 相对旋转轴: 单位化矢量部分 */
rel_vec = (adcs_vec3_t){rel.x, rel.y, rel.z};
(void)adcs_vec3_normalize(&rel_vec, ADCS_EPS_NORM, &axis_unit);

/* 决策表 */
if (st_input.enable == 0) {
    st_state.mode = ST_ACCEPT;
    st_state.rejects = 0U;
} else if (innovation <= st_config.accept_rad) {
    st_state.mode = ST_ACCEPT;
    st_state.rejects = 0U;
} else if (innovation >= st_config.reject_rad) {
    reject_next = st_state.rejects + 1U;
    if (reject_next >= st_config.max_rejects) {
        st_state.rejects = reject_next;
        st_state.mode = ST_FAULT;
    } else {
        st_state.rejects = reject_next;
        st_state.mode = ST_REJECT;
    }
} else {
    /* 滞回带: 保持先前 mode 和 count */
}

st_output.mode = st_state.mode;
st_output.rejects = st_state.rejects;
st_output.innovation_rad = innovation;
st_output.axis = axis_unit;

